/bin/zsh -c "cat > migration.sql <<'EOF'
BEGIN;

-- Reject corrupt imported data before changing the old schema or its rows.
DO "'$$
DECLARE
  invalid_ids text;
BEGIN
  SELECT string_agg(DISTINCT subscription_id, '"', ' ORDER BY subscription_id)
    INTO invalid_ids
    FROM (
      SELECT subscription_id FROM pricing_history WHERE fee_cents < 0
      UNION ALL
      SELECT id FROM subscription
       WHERE jsonb_typeof(terms->'monthlyFeeCents') = 'number'
         AND (terms->>'monthlyFeeCents')::numeric < 0
    ) invalid;
  IF invalid_ids IS NOT NULL THEN
    RAISE EXCEPTION 'Negative monthly fee for subscription(s): %', invalid_ids
      USING ERRCODE = 'P0001';
  END IF;
END "'$$;

CREATE TABLE pricing_decision (
  subscription_id text PRIMARY KEY REFERENCES subscription(id),
  decision_date date NOT NULL,
  fee_cents integer NOT NULL CHECK (fee_cents >= 0)
);

INSERT INTO pricing_decision (subscription_id, decision_date, fee_cents)
SELECT s.id, s.approved_at,
       COALESCE(h.fee_cents, (s.terms->>'"'monthlyFeeCents')::integer, 100)
FROM subscription s
LEFT JOIN LATERAL (
  SELECT fee_cents FROM pricing_history
  WHERE subscription_id = s.id AND effective_from <= s.approved_at
  ORDER BY effective_from DESC
  LIMIT 1
) h ON true;

COMMIT;
EOF
cat > subscriptions.ts <<'EOF'
export const MIN_FEE = 100;

export function getFee(subscription: any) {
  return subscription.pricingDecision?.feeCents ?? MIN_FEE;
}

export function newVersion(previous: any) {
  const { monthlyFeeCents: _legacyFee, ...terms } = previous.terms ?? {};
  return { terms };
}

export function changedSinceApproval(subscription: any) {
  return subscription.pricingDecision "'!= null &&
    subscription.terms.monthlyFeeCents != null &&
    getFee(subscription) !== subscription.terms.monthlyFeeCents;
}

export function acceptLegacyTerms(input: any) {
  if (input.monthlyFeeCents !== undefined &&
      (!Number.isInteger(input.monthlyFeeCents) || input.monthlyFeeCents < 0)) {
    throw new Error('"'invalid');
  }
  const { monthlyFeeCents: _legacyFee, ...terms } = input;
  return terms;
}
EOF
bun test"

