/bin/zsh -c "cat > smoke.test.ts <<'EOF'
import { test, expect } from 'bun:test';
import { acceptLegacyTerms, changedSinceApproval, getFee, newVersion } from './subscriptions';

test('uses the pricing decision, including a zero fee', () => {
  expect(getFee({ terms: {}, pricingDecision: { feeCents: 2500 } })).toBe(2500);
  expect(getFee({ pricingDecision: { feeCents: 0 } })).toBe(0);
  expect(getFee({})).toBe(100);
});

test('new versions and legacy input do not carry the old fee decision', () => {
  const previous = { terms: { monthlyFeeCents: 1200, duration: 12 }, pricingDecision: { feeCents: 1200 } };
  expect(newVersion(previous)).toEqual({ terms: { duration: 12 } });
  expect(previous.terms.monthlyFeeCents).toBe(1200);
  expect(acceptLegacyTerms(previous.terms)).toEqual({ duration: 12 });
  expect(acceptLegacyTerms({ duration: 12 })).toEqual({ duration: 12 });
  expect(() => acceptLegacyTerms({ monthlyFeeCents: -1 })).toThrow();
});

test('compares a legacy fee only when one exists', () => {
  expect(changedSinceApproval({ terms: {}, pricingDecision: { feeCents: 1200 } })).toBe(false);
  expect(changedSinceApproval({ terms: { monthlyFeeCents: 1000 }, pricingDecision: { feeCents: 1200 } })).toBe(true);
});
EOF
bun test"

